import {createHash,randomUUID} from 'node:crypto';
import {Prisma,type PrismaClient} from '../../../../generated/prisma/client';
import type {Identity,OperatorPrincipal} from '../../../../shared/contracts/access';
import type {AcknowledgementReminderPreview,AcknowledgementReminderResult,AdminNoticeSummary,LeadershipNoticeCoverage,NoticeAcknowledgementResult,NoticeDetail,NoticeProposalCommandResult,NoticeProposalDetail,NoticeProposalStatus,NoticeProposalSummary,NoticePublicationResult,NoticeStatus,NoticeSummary,NoticeWithdrawalResult} from '../../../../shared/contracts/communication';
